INSERT INTO `chat_agent_version` (`created_at`, `updated_at`, `deleted_at`, `agent_id`, `description`, `chat_model_ids`, `temperature`, `agent_type`, `prompt_template`, `greeting_message`, `params`, `forest_option`)
VALUES
	('2025-09-25 18:17:58.769', '2025-09-25 18:17:58.769', NULL, @agent_id, '是否可以生成有意义的 ECharts 图表', '[1]', '0.5', 'prompt', '你是一个数据可视化分析助手。\n我会给你一个自然语言问题、一条 SQL 查询语句，以及一个图表类型：\n\n问题：{{input1}}\n\nSQL：{{input2}}\n\n图表类型：{{input3}}（其中，bar=柱状图，line=折线图，pie=饼图 …）\n\n请根据问题和 SQL 字段，判断是否能直接用 ECharts 生成有意义的 {{input3}} 图（bar：柱状图，pie：饼图，line：折线图）。\n\n如果可以生成指定的图表类型，请只返回大写字母 \"Y\"；\n如果不可以生成指定的图表类型，请只返回大写字母 \"N\"。\n\n不要输出任何解释或其他内容。', '', '[{\"input\":\"input1\",\"name\":\"问题\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input2\",\"name\":\"SQL\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true},{\"input\":\"input3\",\"name\":\"图表类型\",\"description\":\"\",\"is_title\":false,\"input_type\":\"text\",\"input_array\":[],\"is_required\":true}]', '{\"prompt_template\":\"\",\"doc_forest_ids\":null}');

SELECT id INTO @agent_version_id FROM chat_agent_version WHERE agent_id = @agent_id ORDER BY id DESC LIMIT 1;
UPDATE `chat_agent` SET `version` = @agent_version_id WHERE id = @agent_id;

COMMIT;

